#!/usr/bin/env python3
"""Bundle the classic browser worker without runtime importScripts requests."""
import argparse
from pathlib import Path

WEB_ROOT = Path(__file__).resolve().parents[1] / 'web'
SOURCES = (
    'vendor/unicorn.js',
    'vendor/fflate.js',
    'graphics.js',
    'runtime.js',
    'worker.js',
)
BANNER = (
    '// Generated by tools/build_worker.py. Edit the source files, then rebuild.\n'
    '// Unicorn.js: GPL-2.0; fflate: MIT. See THIRD-PARTY.md and vendor licenses.\n'
)


def bundle(web_root=WEB_ROOT):
    sections = [BANNER]
    for name in SOURCES:
        # Decode bytes directly so platform newline handling cannot change the build.
        source = (web_root / name).read_bytes().decode('utf-8')
        sections.append(f'\n;\n// ---- {name} ----\n{source}\n')
    return ''.join(sections).encode('utf-8')


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true', help='Fail if the checked-in bundle is stale.')
    args = parser.parse_args()
    output = WEB_ROOT / 'worker.bundle.js'
    expected = bundle()
    if args.check:
        if not output.is_file() or output.read_bytes() != expected:
            parser.exit(1, 'Worker bundle is missing or stale. Run python tools/build_worker.py\n')
        print('Worker bundle matches its source files.')
    else:
        output.write_bytes(expected)
        print(f'Built {output.name}: {len(expected):,} bytes from {len(SOURCES)} source files.')


if __name__ == '__main__':
    main()
